from numbers import Real
import math

def _is_numeric(value):
    return isinstance(value, Real)

def _pearson(xs, ys):
    n = len(xs)
    if n == 0:
        return None

    mean_x = sum(xs) / n
    mean_y = sum(ys) / n

    sxy = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    sxx = sum((x - mean_x) ** 2 for x in xs)
    syy = sum((y - mean_y) ** 2 for y in ys)

    denom = math.sqrt(sxx * syy)
    if denom == 0:
        return None

    return sxy / denom

def most_correlated_columns(data):
    """
    Return the names of the two distinct columns with the largest absolute
    Pearson correlation. The column that appears first in the dict is first
    in the returned tuple.
    """
    if not data or len(data) < 2:
        raise ValueError("data must contain at least two columns")

    names = list(data.keys())
    columns = {}
    length = None

    for name in names:
        raw = data[name]
        try:
            values = list(raw)
        except TypeError:
            raise TypeError(f"column {name!r} is not a list of numbers")

        if length is None:
            length = len(values)
            if length == 0:
                raise ValueError("no data: columns are empty")
        elif len(values) != length:
            raise ValueError("all columns must have the same length")

        for value in values:
            if not _is_numeric(value):
                raise TypeError(f"column {name!r} contains non-numeric value {value!r}")

        columns[name] = values

    best_pair = None
    best_abs = -1.0

    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            corr = _pearson(columns[names[i]], columns[names[j]])
            if corr is None:
                continue

            abs_corr = abs(corr)
            if abs_corr > best_abs:
                best_abs = abs_corr
                best_pair = (names[i], names[j])

    if best_pair is None:
        raise ValueError("could not compute a Pearson correlation (columns may be constant)")

    return best_pair
