def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must not be empty")
    if isinstance(n_clusters, bool) or not isinstance(n_clusters, int) or n_clusters <= 0:
        raise ValueError("n_clusters must be a positive integer")

    k = n_clusters
    n = len(points)
    if k > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    pts = [(float(x), float(y)) for x, y in points]

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    # If every point is its own cluster, the centers are just the points.
    if k == n:
        return sorted([[x, y] for x, y in pts], key=lambda c: (c[0], c[1]))

    # Deterministic initialization: start with the point closest to the mean,
    # then repeatedly add the point farthest from the existing centers.
    mean = (sum(p[0] for p in pts) / n, sum(p[1] for p in pts) / n)
    _, first = min(enumerate(pts), key=lambda t: (dist2(t[1], mean), t[0]))
    centers = [first]

    while len(centers) < k:
        best_point = None
        best_d = -1.0
        for p in pts:
            d = min(dist2(p, c) for c in centers)
            if d > best_d + 1e-12:
                best_d = d
                best_point = p
        centers.append(best_point)

    # Lloyd's algorithm
    for _ in range(300):
        # Assign each point to the nearest center
        new_labels = []
        for p in pts:
            best_j = 0
            best_d = dist2(p, centers[0])
            for j in range(1, k):
                d = dist2(p, centers[j])
                if d < best_d - 1e-12:
                    best_d = d
                    best_j = j
            new_labels.append(best_j)

        # Handle any empty clusters
        counts = [0] * k
        for label in new_labels:
            counts[label] += 1

        for j in range(k):
            if counts[j] == 0:
                best_i = -1
                best_d = -1.0
                for i, p in enumerate(pts):
                    old = new_labels[i]
                    if counts[old] > 1:
                        d = dist2(p, centers[old])
                        if d > best_d + 1e-12:
                            best_d = d
                            best_i = i
                if best_i == -1:
                    best_i = 0
                old = new_labels[best_i]
                new_labels[best_i] = j
                counts[old] -= 1
                counts[j] = 1

        # Recompute centers
        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k
        for p, label in zip(pts, new_labels):
            sums[label][0] += p[0]
            sums[label][1] += p[1]
            counts[label] += 1

        new_centers = []
        for j in range(k):
            if counts[j] > 0:
                new_centers.append([sums[j][0] / counts[j], sums[j][1] / counts[j]])
            else:
                new_centers.append(list(centers[j]))

        shift = max(dist2(new_centers[j], centers[j]) for j in range(k))
        centers = new_centers

        if shift < 1e-12:
            break

    return sorted([[float(x), float(y)] for x, y in centers], key=lambda c: (c[0], c[1]))
