def fit_linear_regression(features, values):
    n = len(features)
    if n == 0:
        raise ValueError("features must not be empty")
    if len(values) != n:
        raise ValueError("features and values must have the same length")

    p = len(features[0])
    for row in features:
        if len(row) != p:
            raise ValueError("all feature rows must have the same length")

    # Design matrix with an intercept column of 1s
    X = [[1.0] + [float(x) for x in row] for row in features]
    y = [float(v) for v in values]
    m = p + 1

    # Normal equations: (X^T X) beta = X^T y
    A = [[0.0] * m for _ in range(m)]
    b = [0.0] * m

    for i in range(n):
        xi = X[i]
        yi = y[i]
        for j in range(m):
            b[j] += xi[j] * yi
            for k in range(m):
                A[j][k] += xi[j] * xi[k]

    # Solve the linear system using Gaussian elimination with partial pivoting
    aug = [A[i][:] + [b[i]] for i in range(m)]

    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) < 1e-12:
            raise ValueError("singular matrix: cannot compute unique OLS coefficients")
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]

        for r in range(col + 1, m):
            factor = aug[r][col] / aug[col][col]
            if factor != 0.0:
                for c in range(col, m + 1):
                    aug[r][c] -= factor * aug[col][c]

    beta = [0.0] * m
    for i in range(m - 1, -1, -1):
        total = aug[i][m]
        for j in range(i + 1, m):
            total -= aug[i][j] * beta[j]
        beta[i] = total / aug[i][i]

    return {
        "coefficients": [float(x) for x in beta[1:]],
        "intercept": float(beta[0]),
    }
