import csv
import re
from io import StringIO

_NUMBER_RE = re.compile(r'^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$')

def _convert_cell(value):
    if value is None or value == '':
        return None

    stripped = value.strip()
    if _NUMBER_RE.fullmatch(stripped):
        try:
            return int(stripped)
        except ValueError:
            try:
                return float(stripped)
            except (ValueError, OverflowError):
                return value

    return value

def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []

    columns = []
    seen_columns = set()
    parsed_docs = []

    for text in csv_texts:
        rows = list(csv.reader(StringIO(text)))
        if not rows:
            parsed_docs.append(({}, []))
            continue

        header = rows[0]
        # Handle a possible UTF-8 BOM at the start of the first header cell
        if header and header[0].startswith('\ufeff'):
            header[0] = header[0][1:]

        for col in header:
            if col not in seen_columns:
                seen_columns.add(col)
                columns.append(col)

        header_index = {}
        for idx, col in enumerate(header):
            if col not in header_index:
                header_index[col] = idx

        parsed_docs.append((header_index, rows[1:]))

    result = []
    for header_index, data_rows in parsed_docs:
        for row in data_rows:
            record = {col: None for col in columns}
            for col, idx in header_index.items():
                if idx < len(row):
                    record[col] = _convert_cell(row[idx])
            result.append(record)

    return result
