import math

def letter_count_correlations(strings):
    if not strings:
        return None

    letters = sorted(set(''.join(strings)))
    n = len(strings)

    # Count each included letter in each string
    counts = {ch: [s.count(ch) for s in strings] for ch in letters}

    # Compute mean and population standard deviation for each letter
    means = {}
    stds = {}
    for ch in letters:
        vals = counts[ch]
        mean = sum(vals) / n
        means[ch] = mean
        variance = sum((v - mean) ** 2 for v in vals) / n
        stds[ch] = math.sqrt(variance)

    # Compute pairwise Pearson correlations
    result = {x: {} for x in letters}
    for x in letters:
        for y in letters:
            if x == y:
                result[x][y] = 1.0
            else:
                cov = sum(
                    (counts[x][i] - means[x]) * (counts[y][i] - means[y])
                    for i in range(n)
                ) / n
                result[x][y] = cov / (stds[x] * stds[y])

    return result
