import math

def standardize_series(x, y, labels):
    if not (len(x) == len(y) == len(labels)):
        raise ValueError("x, y, and labels must have the same number of series")

    def zscore(values):
        n = len(values)
        if n == 0:
            raise ValueError("cannot standardize an empty series")

        mean = sum(values) / n
        std = math.sqrt(sum((v - mean) ** 2 for v in values) / n)

        if std == 0:
            return [0.0 for _ in values]

        return [(v - mean) / std for v in values]

    result = {}
    for label, xs, ys in zip(labels, x, y):
        if len(xs) != len(ys):
            raise ValueError(f"series {label!r}: x and y must have the same length")
        result[label] = [zscore(xs), zscore(ys)]

    return result
```

This uses the population standard deviation, dividing by `n` rather than `n - 1`.

