import csv
import io
import math

def normalize_numeric_columns(csv_text):
    """
    Parse CSV text with a header row and min-max scale every numeric column
    to the range [0, 1]. Non-numeric columns are left unchanged as strings.
    Raises ValueError if there are no numeric columns.
    """
    def _is_numeric(value: str) -> bool:
        s = value.strip()
        if not s:
            return False
        try:
            num = float(s)
            return math.isfinite(num)
        except ValueError:
            return False

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text is empty or has no header row")

    if not header:
        raise ValueError("CSV header row is empty")

    # Build column-wise data
    columns = [[] for _ in header]
    for row in reader:
        for i in range(len(header)):
            cell = row[i] if i < len(row) else ''
            columns[i].append(cell)

    # Determine which columns are numeric
    numeric_flags = []
    for col in columns:
        if col and all(_is_numeric(v) for v in col):
            numeric_flags.append(True)
        else:
            numeric_flags.append(False)

    if not any(numeric_flags):
        raise ValueError("No numeric columns found")

    result = {}
    for name, col, is_num in zip(header, columns, numeric_flags):
        if is_num:
            values = [float(v.strip()) for v in col]
            min_val = min(values)
            max_val = max(values)
            if max_val == min_val:
                scaled = [0.0] * len(values)
            else:
                scaled = [(x - min_val) / (max_val - min_val) for x in values]
            result[name] = scaled
        else:
            result[name] = col  # unchanged list of strings

    return result
