def top_word_counts(csv_text):
    counts = Counter()

    for row in csv.reader(StringIO(csv_text)):
        if not row:
            continue

        text = row[0]
        for word in re.findall(r"\w{2,}", text.lower()):
            if word not in STOP_WORDS:
                counts[word] += 1

