import math

def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("input must not be empty")

    for row in array:
        if len(row) != 5:
            raise ValueError("each row must contain exactly 5 values")

    n = len(array)

    # Extract the five columns
    columns = [[row[i] for row in array] for i in range(5)]

    # Column means and deviations from the mean
    means = [sum(col) / n for col in columns]
    deviations = [
        [value - mean for value in col]
        for col, mean in zip(columns, means)
    ]
    sum_squares = [sum(d * d for d in dev) for dev in deviations]

    matrix = []
    for i in range(5):
        row_corr = []
        for j in range(5):
            if i == j:
                row_corr.append(1.0)
            else:
                denominator = math.sqrt(sum_squares[i] * sum_squares[j])
                if denominator == 0.0:
                    # Constant column; correlation is undefined, use 0.0 off-diagonal
                    row_corr.append(0.0)
                else:
                    numerator = sum(
                        deviations[i][k] * deviations[j][k]
                        for k in range(n)
                    )
                    row_corr.append(numerator / denominator)
        matrix.append(row_corr)

    return matrix
