import csv
import io
import re
from datetime import datetime

_DATE_RE = re.compile(r'[0-9]{4}-[0-9]{2}-[0-9]{2}')

def _is_valid_iso_date(value):
    if not isinstance(value, str) or not _DATE_RE.fullmatch(value):
        return False
    try:
        datetime.strptime(value, '%Y-%m-%d')
    except ValueError:
        return False
    return True

def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    if not (_is_valid_iso_date(start_date) and _is_valid_iso_date(end_date)):
        raise ValueError("start_date and end_date must be valid YYYY-MM-DD dates")

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {column_name!r} not found: CSV header is missing")

    # Handle optional UTF-8 BOM on the first header cell
    if header and header[0].startswith('\ufeff'):
        header[0] = header[0][1:]

    if column_name not in header:
        raise ValueError(f"Column {column_name!r} not found in CSV header")

    col_idx = header.index(column_name)

    result = []
    for row in reader:
        if col_idx < len(row) and start_date <= row[col_idx] <= end_date:
            result.append(row)

    return result
