import csv
import io
import math


def _to_float(value, context):
    """Convert a CSV cell to a finite float, raising ValueError if missing/non-numeric."""
    if value is None:
        raise ValueError(f"Missing value in {context}")
    s = value.strip()
    if not s:
        raise ValueError(f"Missing value in {context}")
    try:
        x = float(s)
    except (TypeError, ValueError, OverflowError):
        raise ValueError(f"Non-numeric value {value!r} in {context}")
    if not math.isfinite(x):
        raise ValueError(f"Non-numeric value {value!r} in {context}")
    return x


def _read_csv(text, name):
    """Parse CSV text into (header, data_rows), validating structure."""
    if not isinstance(text, str):
        raise ValueError(f"{name} must be a string")
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except csv.Error as exc:
        raise ValueError(f"Invalid CSV in {name}: {exc}")

    if not rows:
        raise ValueError(f"{name} has no header row")

    header = [cell.strip().lstrip("\ufeff") for cell in rows[0]]
    if len(set(header)) != len(header):
        raise ValueError(f"{name} has duplicate column names")

    data = rows[1:]
    for i, row in enumerate(data, start=2):
        if len(row) != len(header):
            raise ValueError(f"{name} row {i} has the wrong number of columns")

    return header, data


def _solve_linear_system(A, b):
    """Solve A x = b by Gaussian elimination with partial pivoting."""
    n = len(b)
    if n == 0:
        return []

    scale = max((abs(A[i][j]) for i in range(n) for j in range(n)), default=0.0)
    if scale == 0.0:
        raise ValueError("Singular matrix in linear regression")

    tol = 1e-12 * scale
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = col
        pivot_abs = abs(M[col][col])

        for r in range(col + 1, n):
            v = abs(M[r][col])
            if v > pivot_abs:
                pivot_abs = v
                pivot = r

        if pivot_abs <= tol:
            raise ValueError("Singular matrix in linear regression")

        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pv = M[col][col]
        for r in range(col + 1, n):
            factor = M[r][col] / pv
            if factor != 0.0:
                for c in range(col, n + 1):
                    M[r][c] -= factor * M[col][c]

    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n]
        for j in range(i + 1, n):
            s -= M[i][j] * x[j]
        x[i] = s / M[i][i]

    return x


def predict_linear_regression(train_csv, test_csv, target):
    """Fit OLS regression with intercept on train_csv and predict test_csv rows."""
    if not isinstance(target, str):
        raise ValueError("target must be a string")
    target = target.strip()

    train_header, train_data = _read_csv(train_csv, "train_csv")

    if target not in train_header:
        raise ValueError(f"Target column {target!r} not found in train_csv")

    target_idx = train_header.index(target)
    feature_indices = [i for i in range(len(train_header)) if i != target_idx]
    feature_names = [train_header[i] for i in feature_indices]

    if not train_data:
        raise ValueError("train_csv has no data rows")

    m = len(feature_indices) + 1  # +1 for intercept

    XTX = [[0.0] * m for _ in range(m)]
    Xty = [0.0] * m

    for row_idx, row in enumerate(train_data, start=2):
        feats = [
            _to_float(row[i], f"train_csv row {row_idx}, column {train_header[i]!r}")
            for i in feature_indices
        ]
        y_val = _to_float(row[target_idx], f"train_csv row {row_idx}, column {target!r}")

        x_vec = [1.0] + feats

        for a in range(m):
            xa = x_vec[a]
            Xty[a] += xa * y_val
            xtx_row = XTX[a]
            for b in range(a, m):
                xtx_row[b] += xa * x_vec[b]

    for a in range(m):
        for b in range(a + 1, m):
            XTX[b][a] = XTX[a][b]

    beta = _solve_linear_system(XTX, Xty)

    test_header, test_data = _read_csv(test_csv, "test_csv")
    test_col_index = {name: i for i, name in enumerate(test_header)}

    for name in feature_names:
        if name not in test_col_index:
            raise ValueError(f"test_csv is missing column {name!r}")

    predictions = []
    for row_idx, row in enumerate(test_data, start=2):
        feats = [
            _to_float(row[test_col_index[name]], f"test_csv row {row_idx}, column {name!r}")
            for name in feature_names
        ]
        x_vec = [1.0] + feats

        pred = 0.0
        for j in range(m):
            pred += beta[j] * x_vec[j]

        predictions.append(float(pred))

    return predictions
```

