import csv
import io

def normalize_csv_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)

    if not rows:
        return {}

    header = rows[0]
    data = [row for row in rows[1:] if row]

    columns = {name: [] for name in header}

    for row in data:
        for i, name in enumerate(header):
            columns[name].append(float(row[i]))

    normalized = {}

    for name, values in columns.items():
        if not values:
            normalized[name] = []
            continue

        low = min(values)
        high = max(values)

        if high == low:
            normalized[name] = [0.0 for _ in values]
        else:
            span = high - low
            normalized[name] = [(v - low) / span for v in values]

    return normalized
