def normalize_with_row_averages(data):
    if not data:
        return []

    columns = list(zip(*data))
    col_min = [min(col) for col in columns]
    col_max = [max(col) for col in columns]

    result = []
    for row in data:
        scaled_row = [
            0.0 if col_max[i] == col_min[i]
            else (value - col_min[i]) / (col_max[i] - col_min[i])
            for i, value in enumerate(row)
        ]
        average = sum(scaled_row) / len(scaled_row) if scaled_row else 0.0
        result.append(scaled_row + [average])

    return result
