```python
from html.parser import HTMLParser


class _ArticleParser(HTMLParser):
    VOID_TAGS = {
        'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
        'link', 'meta', 'param', 'source', 'track', 'wbr'
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.results = []
        self.stack = []
        self.container_stack = []
        self.active_collectors = []

    @staticmethod
    def _classes(attrs):
        for name, value in attrs:
            if name == 'class':
                return value.split() if value else []
        return []

    def _start_target(self, fields):
        created = []
        for rec in self.container_stack:
            for field in fields:
                if rec[field] is None and not any(
                    c['rec'] is rec and c['field'] == field
                    for c in self.active_collectors
                ):
                    collector = {'rec': rec, 'field': field, 'buffer': []}
                    self.active_collectors.append(collector)
                    created.append(collector)
        return created

    def handle_starttag(self, tag, attrs):
        if tag in self.VOID_TAGS:
            return

        if tag == 'div':
            classes = self._classes(attrs)
            rec = None
            if 'container' in classes:
                rec = {'title': None, 'date': None, 'author': None}
                self.results.append(rec)
                self.container_stack.append(rec)
            self.stack.append({'tag': tag, 'collectors': [], 'rec': rec})

        elif tag == 'h1':
            created = self._start_target(['title'])
            self.stack.append({'tag': tag, 'collectors': created})

        elif tag == 'span':
            classes = self._classes(attrs)
            fields = []
            if 'date' in classes:
                fields.append('date')
            if 'author' in classes:
                fields.append('author')
            created = self._start_target(fields) if fields else []
            self.stack.append({'tag': tag, 'collectors': created})

        else:
            self.stack.append({'tag': tag, 'collectors': []})

    def handle_endtag(self, tag):
        if not self.stack or self.stack[-1]['tag'] != tag:
            return

        item = self.stack.pop()

        rec = item.get('rec')
        if rec is not None:
            if self.container_stack and self.container_stack[-1] is rec:
                self.container_stack.pop()
            elif rec in self.container_stack:
                self.container_stack.remove(rec)

        for collector in item.get('collectors', []):
            if collector in self.active_collectors:
                self.active_collectors.remove(collector)
            if collector['rec'][collector['field']] is None:
                collector['rec'][collector['field']] = ''.join(collector['buffer']).strip()

    def handle_data(self, data):
        for collector in self.active_collectors:
            collector['buffer'].append(data)

    def close(self):
        super().close()
        for collector in self.active_collectors:
            if collector['rec'][collector['field']] is None:
                collector['rec'][collector['field']] = ''.join(collector['buffer']).strip()
        self.active_collectors.clear()
        self.stack.clear()
        self.container_stack.clear()


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()

    def placeholder(value, default):
        return default if value is None else value

    return [
        (placeholder(rec['title'], 'No Title'),
         placeholder(rec['date'], 'No Date'),
         placeholder(rec['author'], 'No Author'))
        for rec in parser.results
    ]
```

