def _solve_linear_system(A, b):
    """Solve A x = b using Gaussian elimination with partial pivoting."""
    n = len(A)
    if n == 0:
        return []

    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if M[pivot][col] == 0.0:
            raise ValueError("singular matrix")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot_val

        for r in range(n):
            if r != col and M[r][col] != 0.0:
                factor = M[r][col]
                for j in range(col, n + 1):
                    M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]


def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) == 0:
        raise ValueError("training set is empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y must have the same length")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y must have the same length")

    n = len(train_X)
    p = len(train_X[0])

    # Center the training data so the intercept can be handled separately.
    mean_y = sum(float(y) for y in train_y) / n
    means_x = [sum(float(row[j]) for row in train_X) / n for j in range(p)]

    # Build the normal equations for the slopes: (Xc^T Xc) beta = Xc^T yc
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for i in range(n):
        row = train_X[i]
        y = float(train_y[i])
        x_centered = [float(row[j]) - means_x[j] for j in range(p)]
        y_centered = y - mean_y

        for r in range(p):
            b[r] += x_centered[r] * y_centered
            for c in range(p):
                A[r][c] += x_centered[r] * x_centered[c]

    slopes = _solve_linear_system(A, b)
    intercept = mean_y - sum(means_x[j] * slopes[j] for j in range(p))

    # Compute R^2 on the test set.
    ss_res = 0.0
    ss_tot = 0.0
    test_mean = sum(float(y) for y in test_y) / len(test_y) if test_y else 0.0

    for i in range(len(test_X)):
        row = test_X[i]
        pred = intercept + sum(slopes[j] * float(row[j]) for j in range(p))
        y = float(test_y[i])

        resid = y - pred
        ss_res += resid * resid
        ss_tot += (y - test_mean) * (y - test_mean)

    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0

    return float(1.0 - ss_res / ss_tot)
```

