import json

def key_mean_median(json_text):
    records = json.loads(json_text)

    values_by_key = {}

    for record in records:
        if not isinstance(record, dict):
            continue

        for key, value in record.items():
            # Track every key, even if all its values are ignored later
            values_by_key.setdefault(key, [])

            # Ignore booleans, nulls, strings, lists, dicts, etc.
            if isinstance(value, bool):
                continue
            if isinstance(value, (int, float)):
                values_by_key[key].append(value)

    result = {}

    for key, nums in values_by_key.items():
        if not nums:
            result[key] = {"mean": None, "median": None}
        else:
            mean = sum(nums) / len(nums)

            ordered = sorted(nums)
            n = len(ordered)

            if n % 2 == 1:
                median = float(ordered[n // 2])
            else:
                median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2

            result[key] = {"mean": mean, "median": median}

    return result
