def standardize_columns(rows, columns):
    if not rows:
        return {col: [] for col in columns}

    n = len(rows)
    result = {}

    for i, col in enumerate(columns):
        values = [row[i] for row in rows]
        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = math.sqrt(variance)

        if std == 0:
            result[col] = [0.0] * n
        else:
            result[col] = [(x - mean) / std for x in values]

    return result
