import math
from typing import Any, Dict, List

def merge_and_standardize(rows1: List[Dict[str, Any]], rows2: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    rows1 = list(rows1)
    rows2 = list(rows2)

    def is_missing(v: Any) -> bool:
        return v is None or (isinstance(v, float) and math.isnan(v))

    # Collect feature columns from both tables, preserving order
    cols1: List[str] = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)

    cols2: List[str] = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    by_id1 = {row['id']: row for row in rows1}
    by_id2 = {row['id']: row for row in rows2}

    # Compute mean and population std for each first-table feature column,
    # ignoring missing values.
    stats: Dict[str, Any] = {}
    for col in cols1:
        vals = [row.get(col) for row in rows1 if not is_missing(row.get(col))]

        if not vals:
            stats[col] = None
        elif min(vals) == max(vals):
            # Constant column
            stats[col] = (vals[0], 0.0)
        else:
            mean = sum(vals) / len(vals)
            variance = sum((x - mean) ** 2 for x in vals) / len(vals)
            stats[col] = (mean, math.sqrt(variance))

    def zscore(col: str, value: Any) -> Any:
        if is_missing(value):
            return None

        stat = stats[col]
        if stat is None:
            return None

        mean, std = stat
        if std == 0:
            return 0.0
        return (value - mean) / std

    result: List[Dict[str, Any]] = []

    for id_ in sorted(set(by_id1) | set(by_id2)):
        merged: Dict[str, Any] = {'id': id_}

        r1 = by_id1.get(id_)
        for col in cols1:
            merged[col] = zscore(col, r1.get(col)) if r1 is not None else None

        r2 = by_id2.get(id_)
        for col in cols2:
            merged[col] = r2.get(col) if r2 is not None else None

        result.append(merged)

    return result
```

