def seasonal_decomposition(values, period, model):
    if not isinstance(model, str) or model.lower() not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    model = model.lower()

    if isinstance(period, bool) or not isinstance(period, int) or period < 1:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)

    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    # Trend: centered moving average
    trend = [None] * n

    if period % 2 == 1:
        k = period // 2
        for i in range(k, n - k):
            trend[i] = sum(values[i - k:i + k + 1]) / period
    else:
        k = period // 2
        for i in range(k, n - k):
            # 2 x period centered moving average for even periods
            total = (
                0.5 * values[i - k]
                + sum(values[i - k + 1:i + k])
                + 0.5 * values[i + k]
            )
            trend[i] = total / period

    # Detrended series
    detrended = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == "additive":
                detrended[i] = values[i] - trend[i]
            else:
                if trend[i] == 0:
                    raise ValueError(
                        "multiplicative decomposition requires non-zero trend values"
                    )
                detrended[i] = values[i] / trend[i]

    # Raw seasonal indices: average detrended value per phase
    raw = [0.0] * period
    counts = [0] * period

    for i in range(n):
        if detrended[i] is not None:
            phase = i % period
            raw[phase] += detrended[i]
            counts[phase] += 1

    for p in range(period):
        if counts[p] == 0:
            raise ValueError("not enough data to estimate all seasonal indices")
        raw[p] /= counts[p]

    # Normalise seasonal indices to average 0 (additive) or 1 (multiplicative)
    mean_raw = sum(raw) / period

    if model == "additive":
        seasonal_indices = [s - mean_raw for s in raw]
    else:
        if mean_raw == 0:
            raise ValueError(
                "cannot normalise multiplicative seasonal indices to average 1"
            )
        seasonal_indices = [s / mean_raw for s in raw]

    seasonal = [seasonal_indices[i % period] for i in range(n)]

    # Residuals
    residual = [None] * n
    for i in range(n):
        if trend[i] is None:
            residual[i] = None
        elif model == "additive":
            residual[i] = values[i] - trend[i] - seasonal[i]
        else:
            denom = trend[i] * seasonal[i]
            if denom == 0:
                raise ValueError("multiplicative decomposition has a zero denominator")
            residual[i] = values[i] / denom

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
