def scale_table_columns(data):
    cols = list(data)
    kept_rows = [
        row for row in zip(*data.values())
        if all(v is not None for v in row)
    ]

    if not kept_rows:
        return {col: [] for col in cols}

    result = {}
    for i, col in enumerate(cols):
        vals = [row[i] for row in kept_rows]
        lo, hi = min(vals), max(vals)

        if hi == lo:
            result[col] = [0.0] * len(vals)
        else:
            result[col] = [(v - lo) / (hi - lo) for v in vals]

    return result
