    histogram = [0] * 10

    if minimum == maximum:
        histogram[-1] = len(values)
    else:
        span = maximum - minimum
        for value in values:
            index = int((value - minimum) / span * 10)
            if index >= 10:
                index = 9
            histogram[index] += 1

    return {
        "sum": total,
        "mean": total / len(values),
        "min": minimum,
        "max": maximum,
        "histogram": histogram,
    }
