from collections import defaultdict, Counter

def association_chi_square(left, right):
    # Group categories by id, supporting duplicate ids as a true inner join would
    left_by_id = defaultdict(Counter)
    for id_, cat in left:
        left_by_id[id_][cat] += 1

    right_by_id = defaultdict(Counter)
    for id_, cat in right:
        right_by_id[id_][cat] += 1

    # Contingency table: rows = left categories, columns = right categories
    table = defaultdict(Counter)

    for id_ in left_by_id.keys() & right_by_id.keys():
        for lcat, lcount in left_by_id[id_].items():
            for rcat, rcount in right_by_id[id_].items():
                table[lcat][rcat] += lcount * rcount

    if not table:
        return (0.0, 0)

    rows = list(table.keys())
    cols = list({c for row in table.values() for c in row})

    row_totals = {r: sum(table[r].values()) for r in rows}
    col_totals = {c: sum(table[r].get(c, 0) for r in rows) for c in cols}
    n = sum(row_totals.values())

    statistic = 0.0
    for r in rows:
        for c in cols:
            observed = table[r].get(c, 0)
            expected = row_totals[r] * col_totals[c] / n
            statistic += (observed - expected) ** 2 / expected

    dof = (len(rows) - 1) * (len(cols) - 1)
    return (statistic, dof)
