import re

def publication_hour_stats(articles, timezone):
    if not articles:
        raise ValueError("articles list must not be empty")

    for article in articles:
        if 'category' not in article or 'published_time' not in article:
            raise ValueError("each article must contain 'category' and 'published_time'")

    tz = ZoneInfo(timezone)
    hours_by_category = defaultdict(list)

    for article in articles:
        published = article['published_time']

        if isinstance(published, str):
            s = published.strip()
            if s.endswith(('Z', 'z')):
                s = s[:-1] + '+00:00'
            # Normalize offsets like +0000 to +00:00 for compatibility
            s = re.sub(r'([+-]\d{2})(\d{2})$', r'\1:\2', s)
            dt = datetime.fromisoformat(s)
        else:
            dt = published

        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=dt_timezone.utc)

        local_hour = dt.astimezone(tz).hour
        hours_by_category[article['category']].append(local_hour)

    return {
        category: {
            'count': len(hours),
            'mean': sum(hours) / len(hours),
            'min': min(hours),
            'max': max(hours),
        }
        for category, hours in hours_by_category.items()
    }
