import math

def column_correlations(data):
    cols = list(data.keys())
    if not cols:
        return {}

    n = len(next(iter(data.values())))

    if n == 0:
        return {
            x: {y: (1.0 if x == y else float("nan")) for y in cols}
            for x in cols
        }

    means = {c: sum(data[c]) / n for c in cols}
    centered = {c: [v - means[c] for v in data[c]] for c in cols}

    result = {}
    for x in cols:
        result[x] = {}
        for y in cols:
            if x == y:
                result[x][y] = 1.0
                continue

            num = sum(a * b for a, b in zip(centered[x], centered[y]))
            den = math.sqrt(
                sum(a * a for a in centered[x]) *
                sum(b * b for b in centered[y])
            )

            if den == 0:
                # Pearson correlation is undefined if either column is constant
                result[x][y] = float("nan")
            else:
                r = num / den
                # Clamp to valid correlation range to avoid tiny floating-point overshoot
                result[x][y] = max(-1.0, min(1.0, r))

    return result
