import cmath
import math

def spectrum_magnitude_histogram(pairs):
    values = [value for _, value in pairs]
    n = len(values)

    if n == 0:
        return [], []

    # Discrete Fourier transform (unnormalized, negative exponent)
    magnitudes = []
    for k in range(n):
        coeff = 0j
        for t, x in enumerate(values):
            coeff += x * cmath.exp(-2j * math.pi * ((k * t) % n) / n)
        magnitudes.append(abs(coeff))

    # 10 equal-width histogram bins from min to max magnitude
    lo = min(magnitudes)
    hi = max(magnitudes)
    counts = [0] * 10

    if lo == hi:
        counts[-1] = n
    else:
        width = (hi - lo) / 10.0
        for m in magnitudes:
            if m == hi:
                idx = 9
            else:
                idx = int((m - lo) / width)
                if idx < 0:
                    idx = 0
                elif idx > 9:
                    idx = 9
            counts[idx] += 1

    return magnitudes, counts
