import math
from numbers import Real

def normalized_cumulative_sums(data):
    if not isinstance(data, dict) or not data:
        raise ValueError("data must be a non-empty dict")

    # Work with lists so inputs can be validated and processed safely.
    columns = {col: list(vals) for col, vals in data.items()}

    # Type check: non-numeric values raise TypeError.
    for col, vals in columns.items():
        for x in vals:
            if isinstance(x, bool) or not isinstance(x, Real):
                raise TypeError(f"column {col!r} contains non-numeric value: {x!r}")

    # NaN check: any NaN raises ValueError.
    for col, vals in columns.items():
        for x in vals:
            if isinstance(x, float) and math.isnan(x):
                raise ValueError(f"column {col!r} contains NaN")

    result = {}

    for col, vals in columns.items():
        cum = []
        running = 0
        for x in vals:
            running += x
            cum.append(running)

        if not cum:
            result[col] = []
            continue

        lo = min(cum)
        hi = max(cum)

        if hi == lo:
            result[col] = [0.0] * len(cum)
        else:
            result[col] = [float((c - lo) / (hi - lo)) for c in cum]

    return result
