    required = ('id', 'age', 'income')

    for rec in records:
        if not isinstance(rec, dict) or any(key not in rec for key in required):
            raise ValueError("Each record must be a dict with keys 'id', 'age', and 'income'.")

    groups = {}
    for rec in records:
        groups.setdefault(rec['id'], []).append(rec)

    stats = {}
    for gid, group in groups.items():
        n = len(group)
        for field in ('age', 'income'):
            values = [r[field] for r in group]

            if all(v == values[0] for v in values):
                stats[(gid, field)] = (values[0], 0.0)
            else:
                mean = sum(values) / n
                variance = sum((v - mean) ** 2 for v in values) / n
                std = variance ** 0.5
                stats[(gid, field)] = (mean, std)

    result = []
    for rec in records:
        gid = rec['id']
        new_rec = dict(rec)

        for field in ('age', 'income'):
            mean, std = stats[(gid, field)]
            if std == 0.0:
                new_rec[field] = 0.0
            else:
                new_rec[field] = float((rec[field] - mean) / std)

        result.append(new_rec)

    return result
