def cumulative_column_sums(data):
    if not data:
        raise ValueError("table has no rows")

    # Assume equal-length columns; use the first column to get the row count.
    if len(next(iter(data.values()))) == 0:
        raise ValueError("table has no rows")

    result = {}

    for column, values in data.items():
        # Ignore columns that contain any non-numeric value.
        # Booleans are excluded even though bool is a subclass of int.
        if all(isinstance(v, Number) and not isinstance(v, bool) for v in values):
            result[column] = list(accumulate(values))

    if not result:
        raise ValueError("table has no numeric columns")

    return result
