import xml.etree.ElementTree as ET

def xml_to_dict(xml):
    def direct_text(el):
        """Concatenate direct text nodes of an element and trim surrounding whitespace."""
        parts = []
        if el.text:
            parts.append(el.text)
        for child in el:
            if child.tail:
                parts.append(child.tail)
        text = ''.join(parts).strip()
        return text if text else None

    def convert(el):
        # Leaf element with no attributes -> just its text (trimmed), or None
        if not el.attrib and len(el) == 0:
            return direct_text(el)

        result = {}

        # Attributes
        for attr, value in el.attrib.items():
            result['@' + attr] = value

        # Text content, if any
        text = direct_text(el)
        if text is not None:
            result['#text'] = text

        # Child elements
        for child in el:
            child_value = convert(child)
            if child.tag in result:
                existing = result[child.tag]
                if isinstance(existing, list):
                    existing.append(child_value)
                else:
                    result[child.tag] = [existing, child_value]
            else:
                result[child.tag] = child_value

        return result

    try:
        root = ET.fromstring(xml)
    except (ET.ParseError, ValueError) as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc

    return {root.tag: convert(root)}
