import math

def standardize_columns(rows, columns, features):
    result = [list(row) for row in rows]
    col_index = {name: i for i, name in enumerate(columns)}

    for feature in features:
        i = col_index[feature]
        values = [row[i] for row in rows]
        n = len(values)

        if n == 0:
            continue

        # Constant column -> all zeros
        if all(v == values[0] for v in values):
            for row in result:
                row[i] = 0.0
            continue

        mean = sum(values) / n
        std = math.sqrt(sum((v - mean) ** 2 for v in values) / n)

        for original_row, new_row in zip(rows, result):
            new_row[i] = (original_row[i] - mean) / std

    return result
