import math
from numbers import Real

def _is_number(x):
    return isinstance(x, Real) and not isinstance(x, bool)

def row_averages_and_correlations(data):
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("data must be a non-empty list of rows")

    for row in data:
        if not isinstance(row, list) or len(row) == 0:
            raise ValueError("each row must be a non-empty list")

    n_cols = len(data[0])
    for row in data:
        if len(row) != n_cols:
            raise ValueError("data must be rectangular")
        for x in row:
            if not _is_number(x):
                raise ValueError("rows must contain only numbers")

    n_rows = len(data)
    averages = [sum(row) / len(row) for row in data]

    # Transpose to columns
    columns = [[row[j] for row in data] for j in range(n_cols)]
    col_means = [sum(col) / n_rows for col in columns]

    # Center each column
    centered = [[x - col_means[j] for x in columns[j]] for j in range(n_cols)]
    ss = [sum(x * x for x in centered[j]) for j in range(n_cols)]

    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        corr[i][i] = 1.0
        for j in range(i + 1, n_cols):
            if ss[i] == 0.0 or ss[j] == 0.0:
                raise ValueError("Pearson correlation is undefined for a constant column")
            numerator = sum(centered[i][k] * centered[j][k] for k in range(n_rows))
            r = numerator / math.sqrt(ss[i] * ss[j])
            corr[i][j] = r
            corr[j][i] = r

    return (averages, corr)
