import math

def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must not be empty")

    if any(not isinstance(row, list) for row in P):
        raise ValueError("P must be a list of lists")

    m = len(P)
    k = len(P[0])
    if k == 0:
        raise ValueError("P must not be empty")
    if any(len(row) != k for row in P):
        raise ValueError("P must be rectangular")

    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")

    if any(not isinstance(s, list) for s in T):
        raise ValueError("T must be a nested list")

    n = len(T[0])
    if n == 0:
        raise ValueError("T must not be empty")

    if any(not isinstance(row, list) for s in T for row in s):
        raise ValueError("T must be a 3D nested list")

    p = len(T[0][0])
    if p == 0:
        raise ValueError("T must not be empty")

    for s in T:
        if len(s) != n:
            raise ValueError("T must be a regular tensor")
        for row in s:
            if len(row) != p:
                raise ValueError("T must be a regular tensor")

    table = []

    for j in range(n):
        # T[:, j, :] as a k x p matrix
        T_slice = [[T[i][j][q] for q in range(p)] for i in range(k)]

        # P (m x k) times T_slice (k x p)
        product = []
        for i in range(m):
            product_row = []
            for q in range(p):
                value = 0.0
                for l in range(k):
                    value += P[i][l] * T_slice[l][q]
                product_row.append(value)
            product.append(product_row)

        # Flatten row by row
        flat = [product[i][q] for i in range(m) for q in range(p)]
        table.append(flat)

    n_rows = len(table)
    n_cols = len(table[0])

    standardized_cols = []

    for c in range(n_cols):
        col = [table[r][c] for r in range(n_rows)]
        mean = sum(col) / n_rows

        if all(x == col[0] for x in col):
            standardized_cols.append([0.0] * n_rows)
            continue

        variance = sum((x - mean) ** 2 for x in col) / n_rows
        std = math.sqrt(variance)

        if std == 0.0:
            standardized_cols.append([0.0] * n_rows)
        else:
            standardized_cols.append([(x - mean) / std for x in col])

    return [[standardized_cols[c][r] for c in range(n_cols)] for r in range(n_rows)]
```

