def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}

    for col, values in data.items():
        # 1. Apply replacements
        replaced = [replacements.get(v, v) for v in values]

        # 2. Encode any column containing strings
        if any(isinstance(v, str) for v in replaced):
            distinct = sorted(set(replaced))
            mapping = {v: i for i, v in enumerate(distinct)}
            replaced = [mapping[v] for v in replaced]

        # 3. Standardize using sample standard deviation
        n = len(replaced)
        if n == 0:
            result[col] = []
            continue

        mean = sum(replaced) / n
        if n > 1:
            variance = sum((x - mean) ** 2 for x in replaced) / (n - 1)
            std = variance ** 0.5
        else:
            std = 0.0

        if std == 0:
            result[col] = [0.0] * n
        else:
            result[col] = [(x - mean) / std for x in replaced]

    return result
