import math

def summarize_stock_column(column, data):
    column_index = {
        'Open': 1,
        'High': 2,
        'Low': 3,
        'Close': 4,
        'Volume': 5,
    }

    if column not in column_index:
        raise ValueError(f"Invalid column: {column!r}")

    idx = column_index[column]
    values = []

    for row in data:
        try:
            row_len = len(row)
        except TypeError:
            raise ValueError("Each row must have exactly six entries") from None

        if row_len != 6:
            raise ValueError("Each row must have exactly six entries")

        value = row[idx]
        if value is not None:
            values.append(value)

    values.sort()
    n = len(values)

    if n == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None,
        }

    mean = sum(values) / n

    if n > 1:
        variance = sum((v - mean) ** 2 for v in values) / (n - 1)
        std = math.sqrt(variance)
    else:
        std = None  # sample standard deviation is undefined for one value

    def quantile(p):
        # Linear interpolation using position (n - 1) * p
        pos = (n - 1) * p
        lower = math.floor(pos)
        upper = math.ceil(pos)

        if lower == upper:
            return float(values[lower])

        frac = pos - lower
        return float(values[lower] + (values[upper] - values[lower]) * frac)

    return {
        'count': n,
        'mean': float(mean),
        'std': std,
        'min': float(values[0]),
        '25%': quantile(0.25),
        '50%': quantile(0.5),
        '75%': quantile(0.75),
        'max': float(values[-1]),
    }
```

This uses `(n - 1) * p` for quartile positions, which matches the example: for `[100, 102, 104]`, the 25th, 50th, and 75th percentiles are `101.0`, `102.0`, and `103.0`.

