from math import sqrt
from numbers import Real

def correlation_without_column(data, column):
    def is_number(v):
        return isinstance(v, Real)

    # Drop the requested column and any non-numeric columns
    cols = {
        name: values
        for name, values in data.items()
        if name != column and all(is_number(v) for v in values)
    }

    if not cols:
        return None

    names = list(cols)
    n = len(cols[names[0]])

    if n == 0:
        return None

    centered = {}
    sumsq = {}

    for name in names:
        mean = sum(cols[name]) / n
        c = [v - mean for v in cols[name]]
        centered[name] = c
        sumsq[name] = sum(v * v for v in c)

    result = {}

    for x in names:
        result[x] = {}
        for y in names:
            if x == y:
                result[x][y] = 1.0
            else:
                denom = sqrt(sumsq[x] * sumsq[y])
                if denom == 0:
                    result[x][y] = float("nan")  # undefined for constant columns
                else:
                    result[x][y] = float(
                        sum(a * b for a, b in zip(centered[x], centered[y])) / denom
                    )

    return result
