import math

def zscores_by_date(rows):
    if not rows:
        return []

    n = len(rows)
    ncols = len(rows[0][1])

    # Column means
    means = [0.0] * ncols
    for _, vals in rows:
        for j in range(ncols):
            means[j] += vals[j]
    means = [m / n for m in means]

    # Population standard deviation per column
    stds = [0.0] * ncols
    for _, vals in rows:
        for j in range(ncols):
            diff = vals[j] - means[j]
            stds[j] += diff * diff
    stds = [math.sqrt(s / n) for s in stds]

    # Compute z-scores row by row
    result = []
    for date, vals in rows:
        zvals = [
            (vals[j] - means[j]) / stds[j] if stds[j] != 0 else 0.0
            for j in range(ncols)
        ]
        result.append([date] + zvals)

    return result
