def replace_and_standardize(data, features, mapping):
    # Raise ValueError if any feature column is missing
    missing = [col for col in features if col not in data]
    if missing:
        raise ValueError(f"Missing columns in data: {missing}")

    # Replace values in every column, preserving original column order
    replaced = {}
    for col, values in data.items():
        replaced[col] = [mapping.get(value, value) for value in values]

    # Standardize each feature column using population standard deviation
    for col in features:
        values = replaced[col]
        n = len(values)

        if n == 0:
            replaced[col] = []
            continue

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = variance ** 0.5

        if std == 0:
            replaced[col] = [0.0 for _ in values]
        else:
            replaced[col] = [(x - mean) / std for x in values]

    return replaced
