import math

def summarize_with_histogram(pairs, bins):
    if not pairs:
        raise ValueError("pairs must contain at least one value")
    if not isinstance(bins, int) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    values = [float(v) for _, v in pairs]
    n = len(values)

    mean = sum(values) / n
    std = math.sqrt(sum((x - mean) ** 2 for x in values) / n)

    lo = min(values)
    hi = max(values)

    if hi == lo:
        # Degenerate range: all values fall into the last bin.
        density = [0.0] * (bins - 1) + [1.0]
    else:
        width = (hi - lo) / bins
        counts = [0] * bins

        for x in values:
            if x == hi:
                idx = bins - 1
            else:
                idx = int((x - lo) / width)
                if idx < 0:
                    idx = 0
                elif idx >= bins:
                    idx = bins - 1
            counts[idx] += 1

        density = [c / (n * width) for c in counts]

    return {
        "mean": mean,
        "std": std,
        "min": lo,
        "max": hi,
        "density": density,
    }
