    max_count = -1
    for v in values:
        if counts[v] > max_count:
            max_count = counts[v]
            mode = v

    # Population standard deviation
    variance = sum((v - mean) ** 2 for v in values) / n
    std_dev = math.sqrt(variance)

    # Histogram
    min_val = min(values)
    max_val = max(values)
    histogram = [0] * bins

    if min_val == max_val:
        histogram[-1] = n
    else:
        width = (max_val - min_val) / bins
        for v in values:
            if v == max_val:
                idx = bins - 1
            else:
                idx = int((v - min_val) / width + 1e-12)
                if idx < 0:
                    idx = 0
                elif idx >= bins:
                    idx = bins - 1
            histogram[idx] += 1

    return {
        'mean': mean,
        'median': median,
        'mode': mode,
        'std_dev': std_dev,
        'histogram': histogram,
    }
```

