def column_histogram(records, column_name):
    if not records or column_name not in records[0]:
        raise ValueError(f"column {column_name!r} does not exist")

    values = [row[column_name] for row in records]

    # If the column contains strings, map each string to its index
    # in the sorted list of distinct strings.
    if all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        rank = {value: i for i, value in enumerate(distinct)}
        values = [rank[v] for v in values]

    lo, hi = min(values), max(values)
    counts = [0] * 10

    # If all values are equal, they are all the maximum, so they go in the last bin.
    if lo == hi:
        counts[9] = len(values)
        return counts

    width = (hi - lo) / 10.0

    for v in values:
        if v == hi:
            idx = 9
        else:
            idx = int((v - lo) / width + 1e-12)
            if idx < 0:
                idx = 0
            elif idx > 9:
                idx = 9
        counts[idx] += 1

    return counts
