```python
def _solve_linear_system(A, b):
    size = len(A)
    M = [A[i][:] + [b[i]] for i in range(size)]

    max_abs = max((abs(A[i][j]) for i in range(size) for j in range(size)), default=0.0)
    tol = 1e-12 * max_abs

    for col in range(size):
        pivot = max(range(col, size), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) <= tol:
            raise ValueError("singular matrix")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for r in range(col + 1, size):
            factor = M[r][col] / pivot_val
            if factor != 0.0:
                for c in range(col, size + 1):
                    M[r][c] -= factor * M[col][c]

    x = [0.0] * size
    for i in range(size - 1, -1, -1):
        s = M[i][size]
        for j in range(i + 1, size):
            s -= M[i][j] * x[j]
        x[i] = s / M[i][i]

    return x


def fit_linear_regression(rows, targets):
    """Fit ordinary least-squares linear regression with an intercept."""
    if not rows or len(rows) != len(targets):
        raise ValueError("rows must be non-empty and have the same length as targets")

    n = len(rows)
    p = len(rows[0])

    for row in rows:
        if len(row) != p:
            raise ValueError("all feature vectors must have the same length")

    mean_x = [sum(float(row[j]) for row in rows) / n for j in range(p)]
    mean_y = sum(float(t) for t in targets) / n

    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for row, target in zip(rows, targets):
        dx = [float(row[j]) - mean_x[j] for j in range(p)]
        dy = float(target) - mean_y

        for i in range(p):
            b[i] += dx[i] * dy
            for j in range(i, p):
                A[i][j] += dx[i] * dx[j]

    for i in range(p):
        for j in range(i):
            A[i][j] = A[j][i]

    coefficients = _solve_linear_system(A, b) if p > 0 else []
    intercept = mean_y - sum(mean_x[j] * coefficients[j] for j in range(p))

    return coefficients, float(intercept)
```

