import xml.etree.ElementTree as ET

def _direct_text(elem):
    """All direct text nodes of an element: its text plus child tails."""
    parts = []
    if elem.text:
        parts.append(elem.text)
    for child in elem:
        if child.tail:
            parts.append(child.tail)
    return "".join(parts)

def _element_to_value(elem):
    children = list(elem)
    attrs = {f"@{k}": v for k, v in elem.attrib.items()}
    text = _direct_text(elem)

    # Element with no attributes and no children
    if not children and not attrs:
        return text if text != "" else None

    result = dict(attrs)

    if children:
        child_map = {}
        for child in children:
            value = _element_to_value(child)
            tag = child.tag
            if tag in child_map:
                existing = child_map[tag]
                if isinstance(existing, list):
                    existing.append(value)
                else:
                    child_map[tag] = [existing, value]
            else:
                child_map[tag] = value
        result.update(child_map)

    if text != "":
        result["#text"] = text

    return result

def xml_to_dict(s: str) -> dict:
    if isinstance(s, bytes):
        s = s.decode("utf-8")
    if not isinstance(s, str) or not s.strip():
        raise ValueError("input is empty or only whitespace")

    root = ET.fromstring(s)
    return {root.tag: _element_to_value(root)}
