from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.table_depth = 0
        self.target_depth = None
        self.target_found = False

        self.rows = []          # each row is a list of stripped cell strings
        self.in_row = False
        self.row_cells = None
        self.in_cell = False
        self.cell_buffer = []

    def _finalize_cell(self):
        if self.in_cell:
            text = "".join(self.cell_buffer).strip()
            if self.row_cells is not None:
                self.row_cells.append(text)
            self.cell_buffer = []
            self.in_cell = False

    def _finalize_row(self):
        if self.in_row:
            self._finalize_cell()
            if self.row_cells is not None:
                self.rows.append(self.row_cells)
            self.row_cells = None
            self.in_row = False

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            self.table_depth += 1
            if not self.target_found and dict(attrs).get("id") == self.table_id:
                self.target_found = True
                self.target_depth = self.table_depth
            return

        in_target = (
            self.target_depth is not None
            and self.table_depth == self.target_depth
        )

        if tag == "tr":
            if in_target:
                self._finalize_row()
                self.in_row = True
                self.row_cells = []
        elif tag in ("td", "th"):
            if in_target and self.in_row:
                self._finalize_cell()
                self.in_cell = True
                self.cell_buffer = []

    def handle_endtag(self, tag):
        if tag == "table":
            if self.target_depth is not None and self.table_depth == self.target_depth:
                self._finalize_row()
                self.target_depth = None
            self.table_depth -= 1
            return

        in_target = (
            self.target_depth is not None
            and self.table_depth == self.target_depth
        )

        if tag == "tr":
            if in_target and self.in_row:
                self._finalize_row()
        elif tag in ("td", "th"):
            if in_target and self.in_row and self.in_cell:
                self._finalize_cell()

    def handle_data(self, data):
        if self.in_cell:
            self.cell_buffer.append(data)

    def handle_comment(self, data):
        pass

    def close(self):
        super().close()
        if self.target_depth is not None:
            self._finalize_row()
            self.target_depth = None


def html_table_records(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.target_found:
        raise ValueError(f"No table with id {table_id!r}")

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    records = []

    for row in rows[1:]:
        record = {}
        for idx, header in enumerate(headers):
            record[header] = row[idx] if idx < len(row) else ""
        records.append(record)

    return records
```

