            continue

        cell = row[0].strip()
        if not cell:
            continue  # blank line

        if not header_seen:
            header_seen = True
            continue  # skip the header row

        try:
            num = float(cell)
        except ValueError:
            continue  # not a number

        if math.isfinite(num):
            values.append(num)

    if not values:
        return (None, None)

    return (float(statistics.mean(values)), float(statistics.median(values)))
