def cluster_centroids(points, k):
    pts = [(float(x), float(y)) for x, y in points]

    if k <= 0:
        return []
    if k > len(pts):
        raise ValueError("k cannot exceed the number of points")

    # Initial centroids: first k points
    centroids = pts[:k]

    while True:
        clusters = [[] for _ in range(k)]

        # Assign each point to the nearest centroid
        for p in pts:
            dists = [
                (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                for c in centroids
            ]
            idx = min(range(k), key=lambda i: dists[i])
            clusters[idx].append(p)

        # Recompute centroids
        new_centroids = []
        for i, cluster in enumerate(clusters):
            if cluster:
                cx = sum(p[0] for p in cluster) / len(cluster)
                cy = sum(p[1] for p in cluster) / len(cluster)
                new_centroids.append((cx, cy))
            else:
                # Degenerate empty cluster: keep old centroid
                new_centroids.append(centroids[i])

        # Stop when centroids no longer change
        if new_centroids == centroids:
            return sorted(new_centroids)

        centroids = new_centroids
