import math

def _five_number_summary(scores):
    vals = sorted(float(s) for s in scores)
    n = len(vals)

    def percentile(p):
        rank = p * (n - 1)
        lo = math.floor(rank)
        frac = rank - lo
        if frac == 0:
            return vals[lo]
        return vals[lo] * (1.0 - frac) + vals[lo + 1] * frac

    return [
        vals[0],
        percentile(0.25),
        percentile(0.5),
        percentile(0.75),
        vals[-1],
    ]


def country_score_summary(records):
    required = ("Name", "Country", "Score")

    if records is None:
        raise ValueError("records must be a non-empty list of dicts")

    try:
        records = list(records)
    except TypeError:
        raise ValueError("records must be an iterable of dicts")

    if not records:
        raise ValueError("records must not be empty")

    for rec in records:
        if not isinstance(rec, dict) or any(key not in rec for key in required):
            raise ValueError("each record must contain 'Name', 'Country', and 'Score'")

    # Keep only the first record for each name
    first_by_name = {}
    for rec in records:
        name = rec["Name"]
        if name not in first_by_name:
            first_by_name[name] = rec

    scores_by_country = {}
    for rec in first_by_name.values():
        scores_by_country.setdefault(rec["Country"], []).append(rec["Score"])

    return {
        country: _five_number_summary(scores)
        for country, scores in scores_by_country.items()
    }
