from numbers import Number

def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    # Validate that every value is a real numeric type.
    for name, values in columns.items():
        for value in values:
            if isinstance(value, complex) or not isinstance(value, Number):
                raise TypeError(f"column {name!r} contains non-numeric value: {value!r}")

    lengths = {len(values) for values in columns.values()}
    if len(lengths) != 1:
        raise ValueError("all columns must have the same length")

    n = next(iter(lengths))
    if n == 0:
        raise ValueError("table has no rows")
    if n < 2:
        raise ValueError("table must have at least two rows")

    means = {name: sum(values) / n for name, values in columns.items()}
    deviations = {
        name: [value - means[name] for value in values]
        for name, values in columns.items()
    }

    result = {}
    for a in columns:
        result[a] = {}
        for b in columns:
            result[a][b] = sum(
                deviations[a][i] * deviations[b][i] for i in range(n)
            ) / (n - 1)

    return result
```

