def summarize_student_records(data):
    required_keys = ("Name", "Age", "Score")
    if any(key not in data for key in required_keys):
        raise ValueError("data must contain 'Name', 'Age', and 'Score'")

    names = data["Name"]
    ages = data["Age"]
    scores = data["Score"]

    # Build records and sort stably by name, then age
    records = [[name, age, score] for name, age, score in zip(names, ages, scores)]
    records.sort(key=lambda record: (record[0], record[1]))

    # Average score per name
    score_sum = {}
    score_count = {}
    for name, _, score in records:
        score_sum[name] = score_sum.get(name, 0) + score
        score_count[name] = score_count.get(name, 0) + 1

    average_scores = {
        name: score_sum[name] / score_count[name]
        for name in score_sum
    }

    # Most common age, or None if no records
    if ages:
        age_count = {}
        for age in ages:
            age_count[age] = age_count.get(age, 0) + 1
        most_common_age = max(age_count, key=age_count.get)
    else:
        most_common_age = None

    return records, average_scores, most_common_age
