def classification_summary(y_true, y_pred):
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")

    n = len(y_true)

    # Preserve first-seen label order from y_true, then y_pred.
    labels = []
    seen = set()
    for label in y_true:
        if label not in seen:
            seen.add(label)
            labels.append(label)
    for label in y_pred:
        if label not in seen:
            seen.add(label)
            labels.append(label)

    support = {label: 0 for label in labels}
    predicted = {label: 0 for label in labels}
    true_positive = {label: 0 for label in labels}

    for t, p in zip(y_true, y_pred):
        support[t] += 1
        predicted[p] += 1
        if t == p:
            true_positive[t] += 1

    report = {}
    for label in labels:
        tp = true_positive[label]

        precision = tp / predicted[label] if predicted[label] else 0.0
        recall = tp / support[label] if support[label] else 0.0
        f1 = (
            2 * precision * recall / (precision + recall)
            if precision + recall
            else 0.0
        )

        report[label] = (precision, recall, f1, support[label])

    correct = sum(t == p for t, p in zip(y_true, y_pred))
    report["accuracy"] = correct / n if n else 0.0

    if labels:
        macro_precision = sum(report[label][0] for label in labels) / len(labels)
        macro_recall = sum(report[label][1] for label in labels) / len(labels)
        macro_f1 = sum(report[label][2] for label in labels) / len(labels)
    else:
        macro_precision = macro_recall = macro_f1 = 0.0
    report["macro avg"] = (macro_precision, macro_recall, macro_f1, n)

    if n:
        weighted_precision = sum(report[label][0] * report[label][3] for label in labels) / n
        weighted_recall = sum(report[label][1] * report[label][3] for label in labels) / n
        weighted_f1 = sum(report[label][2] * report[label][3] for label in labels) / n
    else:
        weighted_precision = weighted_recall = weighted_f1 = 0.0
    report["weighted avg"] = (weighted_precision, weighted_recall, weighted_f1, n)

    return report
