import csv
import io
import math

def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        header = []

    # Check requested columns before processing data
    for col in columns:
        if col not in header:
            raise KeyError(col)

    data = {name: [] for name in header}

    for row in reader:
        if not row:
            continue
        if len(row) != len(header):
            raise ValueError(f"Expected {len(header)} fields, got {len(row)}")

        for name, value in zip(header, row):
            try:
                num = float(value)
            except (TypeError, ValueError):
                raise ValueError(
                    f"Non-numeric value {value!r} in column {name!r}"
                ) from None
            data[name].append(num)

    def cube_root(x):
        if x == 0:
            return 0.0
        # Preserve sign for negative numbers
        return math.copysign(abs(x) ** (1.0 / 3.0), x)

    roots = {col: [cube_root(v) for v in data[col]] for col in columns}

    return data, roots
