import csv
import io
import math

def correlation_matrix_from_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    columns = {name: [] for name in header}

    for row in reader:
        if not row:
            continue
        for name, value in zip(header, row):
            columns[name].append(float(value))

    names = list(header)
    result = {name: {} for name in names}

    means = {}
    for name in names:
        vals = columns[name]
        means[name] = sum(vals) / len(vals) if vals else float("nan")

    def pearson(xs, ys, mx, my):
        if not xs or len(xs) != len(ys):
            return float("nan")

        numerator = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
        ss_x = sum((x - mx) ** 2 for x in xs)
        ss_y = sum((y - my) ** 2 for y in ys)

        denominator = math.sqrt(ss_x * ss_y)
        if denominator == 0:
            return float("nan")

        return numerator / denominator

    for i, a in enumerate(names):
        result[a][a] = 1.0
        for b in names[i + 1:]:
            r = pearson(columns[a], columns[b], means[a], means[b])
            result[a][b] = r
            result[b][a] = r

    return result
```

This uses only the standard library. Diagonal entries are `1.0`; off-diagonal correlations involving a constant column are returned as `float("nan")` because Pearson correlation is undefined there.

