from numbers import Number

def _is_numeric(value):
    # Exclude complex numbers because they cannot be ordered into a real [0, 1] range.
    return isinstance(value, Number) and not isinstance(value, complex)

def normalize_columns(data):
    if not data:
        raise ValueError("data dictionary is empty")

    normalized = {}

    for key, column in data.items():
        if any(not _is_numeric(value) for value in column):
            raise ValueError(f"column {key!r} contains non-numeric values")

        if not column:
            normalized[key] = []
            continue

        try:
            col_min = min(column)
            col_max = max(column)

            if col_min == col_max:
                normalized[key] = [0.0] * len(column)
            else:
                span = col_max - col_min
                normalized[key] = [float((value - col_min) / span) for value in column]
        except TypeError:
            raise ValueError(f"column {key!r} contains non-numeric values")

    return normalized
```

