def fit_joined_regression(feature_rows, target_rows, features, target):
    target_by_id = {row["id"]: row for row in target_rows}

    joined = []
    for frow in feature_rows:
        if frow["id"] in target_by_id:
            joined.append((frow, target_by_id[frow["id"]]))

    if not joined:
        raise ValueError("No common ids between feature_rows and target_rows")

    features = list(features)
    p = len(features) + 1  # +1 for intercept

    X = [[1.0] + [float(frow[f]) for f in features] for frow, _ in joined]
    y = [float(trow[target]) for _, trow in joined]

    # Normal equations: (X^T X) beta = X^T y
    xtx = [[sum(row[i] * row[j] for row in X) for j in range(p)] for i in range(p)]
    xty = [sum(row[i] * yi for row, yi in zip(X, y)) for i in range(p)]

    # Solve linear system with Gaussian elimination + partial pivoting
    aug = [xtx[i][:] + [xty[i]] for i in range(p)]

    for col in range(p):
        pivot = max(range(col, p), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) < 1e-12:
            raise ValueError("Singular matrix; cannot fit unique OLS coefficients")

        aug[col], aug[pivot] = aug[pivot], aug[col]
        pivot_val = aug[col][col]

        for j in range(col, p + 1):
            aug[col][j] /= pivot_val

        for r in range(p):
            if r != col and aug[r][col] != 0.0:
                factor = aug[r][col]
                for j in range(col, p + 1):
                    aug[r][j] -= factor * aug[col][j]

    beta = [aug[i][p] for i in range(p)]

    intercept = float(beta[0])
    coefficients = [float(b) for b in beta[1:]]

    residuals = []
    for row, yi in zip(X, y):
        pred = sum(row[i] * beta[i] for i in range(p))
        residuals.append(float(yi - pred))

    return {
        "coefficients": coefficients,
        "intercept": intercept,
        "residuals": residuals,
    }
