from collections import defaultdict
import math

def _linear_quantile(sorted_values, q):
    """Return the q-quantile using linear interpolation."""
    n = len(sorted_values)
    if n == 1:
        return float(sorted_values[0])

    pos = (n - 1) * q
    lo = math.floor(pos)
    hi = math.ceil(pos)

    if lo == hi:
        return float(sorted_values[lo])

    frac = pos - lo
    return float(sorted_values[lo] * (1 - frac) + sorted_values[hi] * frac)


def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = defaultdict(list)

    for fruit, day, sales in records:
        sales_by_fruit[fruit].append(sales)

    stats = {}

    for fruit, sales in sales_by_fruit.items():
        sales.sort()
        stats[fruit] = (
            _linear_quantile(sales, 0.0),   # min
            _linear_quantile(sales, 0.25),  # Q1
            _linear_quantile(sales, 0.5),   # median
            _linear_quantile(sales, 0.75),  # Q3
            _linear_quantile(sales, 1.0),   # max
        )

    return stats
