from collections import Counter

def column_summary_stats(table, mapping, features):
    # Validate requested features first
    for feature in features:
        if feature not in table:
            raise ValueError(f"Feature not in table: {feature!r}")

    def replace(value):
        for key, replacement in mapping.items():
            if value == key:
                return replacement
        return value

    result = {}

    for feature in features:
        values = [replace(v) for v in table[feature]]
        n = len(values)

        if n == 0:
            raise ValueError(f"Column {feature!r} is empty")

        mean = sum(values) / n

        ordered = sorted(values)
        mid = n // 2
        if n % 2 == 1:
            median = float(ordered[mid])
        else:
            median = float((ordered[mid - 1] + ordered[mid]) / 2)

        counts = Counter(values)
        max_count = max(counts.values())
        mode = min(v for v, count in counts.items() if count == max_count)

        variance = sum((v - mean) ** 2 for v in values) / n  # population variance

        result[feature] = {
            "mean": mean,
            "median": median,
            "mode": mode,
            "variance": variance,
        }

    return result
