def standardize_columns(rows, scale_cols):
    if not rows:
        return []

    n = len(rows)
    result = [list(row) for row in rows]

    for col in scale_cols:
        vals = [row[col] for row in rows]

        # Constant column: no variation, so z-scores are all zero.
        if all(v == vals[0] for v in vals):
            for i in range(n):
                result[i][col] = 0.0
            continue

        mean = sum(vals) / n
        variance = sum((v - mean) ** 2 for v in vals) / n
        std = variance ** 0.5

        if std == 0.0:
            for i in range(n):
                result[i][col] = 0.0
        else:
            for i in range(n):
                result[i][col] = (rows[i][col] - mean) / std

    return result
