from html.parser import HTMLParser

class _LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self._open_links = []

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            href = next((value for name, value in attrs if name == "href"), None)
            link = {"href": href, "parts": []}
            self.links.append(link)
            self._open_links.append(link)

    def handle_endtag(self, tag):
        if tag == "a" and self._open_links:
            self._open_links.pop()

    def handle_data(self, data):
        for link in self._open_links:
            link["parts"].append(data)


def extract_links(html):
    parser = _LinkExtractor()
    parser.feed(html)
    parser.close()
    return [("".join(link["parts"]), link["href"]) for link in parser.links]
