from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False
        self.active = False
        self.depth = 0
        self.headers = []
        self.rows = []
        self.row = None
        self.cell = None
        self.cell_tag = None

    def _end_cell(self):
        if self.cell is None:
            return
        text = ''.join(self.cell).strip()
        if self.cell_tag == 'th':
            self.headers.append(text)
        elif self.row is not None:
            self.row.append(text)
        self.cell = None
        self.cell_tag = None

    def _end_row(self):
        if self.row:
            self.rows.append(self.row)
        self.row = None

    def handle_starttag(self, tag, attrs):
        if not self.active:
            if tag == 'table':
                self.active = True
                self.found_table = True
                self.depth = 1
                self.headers = []
                self.rows = []
                self.row = None
                self.cell = None
                self.cell_tag = None
            return

        if tag == 'table':
            self.depth += 1
            return

        if self.depth == 1:
            if tag == 'tr':
                self._end_cell()
                self._end_row()
                self.row = []
            elif tag in ('td', 'th'):
                self._end_cell()
                self.cell = []
                self.cell_tag = tag

    def handle_data(self, data):
        if self.active and self.cell is not None:
            self.cell.append(data)

    def handle_endtag(self, tag):
        if not self.active:
            return

        if tag == 'table':
            self.depth -= 1
            if self.depth == 0:
                self._end_cell()
                self._end_row()
                self.active = False
            return

        if self.depth == 1:
            if tag in ('td', 'th'):
                self._end_cell()
            elif tag == 'tr':
                self._end_row()

    def finalize(self):
        if self.active:
            self._end_cell()
            self._end_row()
            self.active = False


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser.finalize()

    if not parser.found_table:
        raise ValueError("no table found")
    if not parser.rows:
        raise ValueError("table has no data rows")

    return parser.headers, parser.rows
