import math

def row_zscores_and_correlation(data):
    if not data:
        return [], []

    n_cols = len(data[0])
    z_rows = []

    # Standardise each row using its mean and population std dev
    for row in data:
        if len(row) != n_cols:
            raise ValueError("All rows must have the same length")

        n = len(row)
        if n == 0:
            z_rows.append([])
            continue

        mean = sum(row) / n
        variance = sum((x - mean) ** 2 for x in row) / n
        std = math.sqrt(variance)

        if std == 0.0:
            z_rows.append([0.0] * n)
        else:
            z_rows.append([(x - mean) / std for x in row])

    if not z_rows or n_cols == 0:
        return z_rows, []

    m = len(z_rows)
    p = n_cols

    # Transpose to work with columns
    cols = list(zip(*z_rows))

    # Pearson correlation requires centering each column by its own mean
    col_means = [sum(col) / m for col in cols]
    centered_cols = [
        [x - col_means[j] for x in cols[j]]
        for j in range(p)
    ]
    sum_sq = [sum(x * x for x in centered) for centered in centered_cols]

    corr = [[0.0] * p for _ in range(p)]

    for i in range(p):
        for j in range(i, p):
            if i == j:
                val = 1.0
            else:
                denom = math.sqrt(sum_sq[i] * sum_sq[j])
                if denom == 0.0:
                    val = float('nan')
                else:
                    numerator = sum(
                        centered_cols[i][k] * centered_cols[j][k]
                        for k in range(m)
                    )
                    val = numerator / denom

            corr[i][j] = val
            corr[j][i] = val

    return z_rows, corr
