from numbers import Real
import math

def _is_numeric_column(values):
    return all(isinstance(v, Real) for v in values)

def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    n = len(next(iter(table.values())))
    if n == 0:
        raise ValueError("table is empty")

    numeric_cols = [name for name, vals in table.items() if _is_numeric_column(vals)]
    if not numeric_cols:
        raise ValueError("no numeric columns")

    numeric_set = set(numeric_cols)
    standardized = {}
    means = {}

    for name, vals in table.items():
        if name in numeric_set:
            mean = sum(vals) / n
            variance = sum((v - mean) ** 2 for v in vals) / n
            std = math.sqrt(variance)

            if std == 0:
                raise ValueError(f"cannot standardize constant numeric column {name!r}")

            means[name] = mean
            standardized[name] = [(v - mean) / std for v in vals]
        else:
            standardized[name] = vals

    k = len(numeric_cols)
    corr = [[0.0] * k for _ in range(k)]

    for i, ci in enumerate(numeric_cols):
        corr[i][i] = 1.0
        xi = table[ci]
        mi = means[ci]
        ss_i = sum((v - mi) ** 2 for v in xi)

        for j in range(i + 1, k):
            cj = numeric_cols[j]
            xj = table[cj]
            mj = means[cj]

            num = sum((a - mi) * (b - mj) for a, b in zip(xi, xj))
            ss_j = sum((b - mj) ** 2 for b in xj)

            r = num / math.sqrt(ss_i * ss_j)
            corr[i][j] = r
            corr[j][i] = r

    return standardized, corr
```

