import json
from html import unescape
from html.parser import HTMLParser

class _TitleParser(HTMLParser):
    # Treat <title> like script/style so markup inside it is not parsed as tags.
    CDATA_CONTENT_ELEMENTS = ("script", "style", "title")

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self._in_title = False
        self._found = False
        self._chunks = []
        self._done = False

    def handle_starttag(self, tag, attrs):
        if self._done:
            return
        if tag == "title" and not self._in_title:
            self._in_title = True
            self._found = True

    def handle_endtag(self, tag):
        if self._done:
            return
        if tag == "title" and self._in_title:
            self._in_title = False
            self._done = True

    def handle_data(self, data):
        if self._in_title and not self._done:
            self._chunks.append(data)

    def get_title(self):
        if not self._found:
            return None
        return unescape("".join(self._chunks))

def extract_title_json(html):
    parser = _TitleParser()
    parser.feed(html)
    parser.close()
    return json.dumps({"title": parser.get_title()})
```

Example:

```python
extract_title_json("<html><head><title>Hello World</title></head></html>")
# '{"title": "Hello World"}'

extract_title_json("<html><head></head></html>")
# '{"title": null}'
```

